import re
from collections import defaultdict


def parse_shard_splits(log_text: str):
    """Parse shard split events from log text.

    Returns:
        - children_map: dict[int, list[int]] mapping parent shard -> ordered child shards
        - shard_info: dict[int, dict] with keys: created_at (str), size (int)
    """
    pattern = re.compile(
        r"^\[(?P<ts>[^\]]+)\].*?split_shards: splitted\. ShardInfo \{[^}]*?shard_id:\s*(?P<parent>\d+)[^}]*?}.*?===>\s*shard_id:\s*(?P<c1>\d+),shard_id:\s*(?P<c2>\d+).*?new_sizes:\s*\"size:\s*(?P<s1>\d+),size:\s*(?P<s2>\d+)\"",
        re.MULTILINE,
    )

    children_map: dict[int, list[int]] = defaultdict(list)
    shard_info: dict[int, dict] = {}

    for m in pattern.finditer(log_text):
        ts = m.group("ts").split()[0]
        parent = int(m.group("parent"))
        c1 = int(m.group("c1"))
        c2 = int(m.group("c2"))
        s1 = int(m.group("s1"))
        s2 = int(m.group("s2"))

        if c1 not in children_map[parent]:
            children_map[parent].append(c1)
        if c2 not in children_map[parent]:
            children_map[parent].append(c2)

        shard_info.setdefault(c1, {"created_at": ts, "size": s1})
        shard_info.setdefault(c2, {"created_at": ts, "size": s2})
        shard_info.setdefault(parent, {"created_at": None, "size": None})

    return children_map, shard_info


def find_roots(children_map: dict[int, list[int]]):
    parents = set(children_map.keys())
    childs = {c for cs in children_map.values() for c in cs}
    roots = sorted(parents - childs)
    if not roots and childs:
        return [min(childs)]
    return roots


def print_shard_tree(children_map: dict[int, list[int]], shard_info: dict[int, dict], roots: list[int]):
    def dfs(node: int, depth: int):
        info = shard_info.get(node, {"created_at": None, "size": None})
        created_at = info.get("created_at")
        size = info.get("size")
        meta = ""
        if created_at or size is not None:
            t = created_at if created_at else "-"
            sz = str(size) if size is not None else "-"
            meta = f"\t{t}, size={sz}"
        print("\t" * depth + f"{node}" + meta)
        for child in children_map.get(node, []):
            dfs(child, depth + 1)

    for root in roots:
        dfs(root, 0)


if __name__ == "__main__":
    children_map, shard_info = parse_shard_splits(S)
    roots = find_roots(children_map)
    if not roots:
        roots = [1]
        shard_info.setdefault(1, {"created_at": None, "size": None})
    print_shard_tree(children_map, shard_info, roots)
